"""Compile checked JSON rule sheets to Python data and matching C# definitions.

This generator does NOT verify hooks or produce a playable game mod.
"""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def generate():
    powers = json.loads((ROOT / "sheets/powerups.json").read_text())
    scoring = json.loads((ROOT / "sheets/scoring.json").read_text())
    dest_py = ROOT / "src/combat_golf/generated_rules.py"
    dest_py.write_text(
        '# Generated by tools/generate.py from sheets/*.json; do not edit.\n'
        'POWERUPS = ' + repr({row['id']: row for row in powers}) + '\n'
        'SCORING = ' + repr({row['id']: row for row in scoring}) + '\n'
    )
    def cs_str(s):
        return json.dumps(s, ensure_ascii=True)
    parts = [
        '// Generated by tools/generate.py from sheets/*.json; do not edit.',
        'namespace CombatGolf {',
        '  internal sealed class PowerRule {',
        '    public readonly string Id, Name, Target, Effect;',
        '    public readonly int Points, DurationSeconds, CooldownSeconds;',
        '    public readonly float Strength;',
        '    public PowerRule(string id,string name,int pts,string target,string effect,int duration,float strength,int cooldown) {',
        '      Id=id; Name=name; Points=pts; Target=target; Effect=effect;',
        '      DurationSeconds=duration; Strength=strength; CooldownSeconds=cooldown;',
        '    }',
        '  }',
        '  internal static class GeneratedRules {',
        '    public static readonly PowerRule[] Powers = new PowerRule[] {',
    ]
    for r in powers:
        args = [cs_str(r['id']), cs_str(r['name']), str(r['points']), cs_str(r['target']), cs_str(r['effect']), str(r['duration_seconds']), str(float(r['strength'])) + 'f', str(r['cooldown_seconds'])]
        parts.append('      new PowerRule(' + ', '.join(args) + '),')
    parts += ['    };', '  }', '}']
    (ROOT / "golf-plugin/GeneratedRules.cs").write_text('\n'.join(parts) + '\n')
    return powers, scoring


if __name__ == '__main__':
    p,s = generate()
    print(f'Generated {len(p)} power rules and {len(s)} scoring rules')
